import{_ as n,C as o,o as r,c as s,a3 as i,E as d,w as l,j as t}from"./chunks/framework.ChMUB7od.js";const h="/versions/v0.16.29/screens/macros/macro_pitch_bend.png",v=JSON.parse('{"title":"Pitch Bend","description":"","frontmatter":{"title":"Pitch Bend","pageClass":"macro-doc"},"headers":[],"relativePath":"macros/pitch-bend.md","filePath":"macros/pitch-bend.md"}'),c={name:"macros/pitch-bend.md"};function u(m,e,p,b,g,f){const a=o("ManualRelated");return r(),s("div",null,[e[1]||(e[1]=i('<h1 id="pitch-bend" tabindex="-1">Pitch Bend <a class="header-anchor" href="#pitch-bend" aria-label="Permalink to &quot;Pitch Bend&quot;">​</a></h1><p><strong>Firmware menu name:</strong> PITCH BEND</p><p>Send channel-wide 14-bit MIDI Pitch Bend.</p><p><img src="'+h+'" alt="Pitch Bend macro" class="screen"></p><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h2><p>Use <strong>Pitch Bend</strong> to drive the MIDI pitch bend wheel from a knob. Bend is channel-wide, so there is no CC number to set — just a channel. The range is the full 14-bit bend span (0-16383, centre 8192), which by default puts the bend centre at the knob&#39;s midpoint. Narrow Min/Max to limit how far the knob can bend, or set both to the same value to pin the bend.</p><h2 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h2><div class="device-params-table"><table tabindex="0"><thead><tr><th>Parameter</th><th>Range</th><th>What it does</th></tr></thead><tbody><tr><td>Mode</td><td>—</td><td>Macro output type. Change this to switch between MIDI, internal routing, and CV16 targets.</td></tr><tr><td>Minimum</td><td>Mode-specific</td><td>Value sent when the knob is at minimum travel. Units follow the target (MIDI 0–127, 14-bit 0–16383, device parameter native range, CV volts, LFO %, etc.).</td></tr><tr><td>Maximum</td><td>Mode-specific</td><td>Value sent when the knob is at maximum travel. Must be greater than or equal to <strong>Minimum</strong>.</td></tr><tr><td>Channel</td><td>Global, 1 – 16</td><td>MIDI channel for outgoing messages. <strong>Global</strong> uses the project&#39;s global channel setting.</td></tr><tr><td>Invert</td><td>True / False</td><td>When <strong>True</strong>, knob clockwise motion maps to decreasing values (minimum ↔ maximum swapped).</td></tr><tr><td>Outputs</td><td>USB / DIN / combos</td><td>Which physical MIDI outputs carry this macro: USB, <strong>Out 1</strong>, <strong>Out 2</strong>, or combined masks.</td></tr></tbody></table></div><h2 id="midi-outputs" tabindex="-1">MIDI outputs <a class="header-anchor" href="#midi-outputs" aria-label="Permalink to &quot;MIDI outputs&quot;">​</a></h2><p>The <strong>Outputs</strong> field selects one of these port combinations:</p><ul><li>None</li><li>USB</li><li>Out 1</li><li>USB + Out 1</li><li>Out 2</li><li>USB + Out 2</li><li>Out 1 + Out 2</li><li>USB + Out 1 + Out 2</li></ul>',11)),d(a,{title:"Related topics"},{default:l(()=>[...e[0]||(e[0]=[t("ul",null,[t("li",null,[t("a",{href:"/versions/v0.16.29/macros/"},"Macros overview")]),t("li",null,[t("a",{href:"/versions/v0.16.29/macros/setting-up-macros"},"Setting up macros")]),t("li",null,[t("a",{href:"/versions/v0.16.29/concepts/modulation"},"Modulation")])],-1)])]),_:1})])}const M=n(c,[["render",u]]);export{v as __pageData,M as default};
